"use client";

/**
 * Ctrl+K search overlay; advanced syntax requires `advanced_search`.
 *
 * Must call (do not reimplement): isEnabled
 */
import { useEffect, useState } from "react";
import { Dialog } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Spinner } from "@/components/ui/spinner";
import { ANONYMOUS_FLAG_CONTEXT } from "@/hooks/flag-context";
import { useDebouncedValue } from "@/hooks/use-debounced-value";
import { isEnabled } from "@/lib/feature-flags";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchHit } from "@/server/services/search-service";
import type { ActionResult } from "@/types/api";
import type { OrgId } from "@/types/common";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { ReactElement } from "react";
import { describeQuery, parseSearchQuery } from "./query-syntax";
import { SearchResults } from "./search-results";

export type SearchDialogProps = {
  open: boolean;
  orgId: OrgId;
  flags: FeatureFlagSnapshot;
  onClose: () => void;
  onSearch: (input: SearchQueryInput) => Promise<ActionResult<SearchHit[]>>;
};

const SEARCH_PAGE_SIZE = 20;

export function SearchDialog(props: SearchDialogProps): ReactElement | null {
  const { open, orgId, flags, onClose, onSearch } = props;

  const [raw, setRaw] = useState("");
  // Results are stored together with the query that produced them, so
  // "still searching" is derived rather than a second piece of state that
  // could disagree with the first.
  const [results, setResults] = useState<{
    query: string;
    hits: readonly SearchHit[];
  }>({ query: "", hits: [] });

  const debounced = useDebouncedValue(raw);
  const advanced =
    flags.advanced_search === true ||
    isEnabled("advanced_search", { ...ANONYMOUS_FLAG_CONTEXT, orgId });
  const parsed = parseSearchQuery(debounced, advanced);

  const query = parsed.text;
  const pending = query.length > 0 && results.query !== query;

  useEffect(() => {
    if (!open || query.length === 0) return;

    let cancelled = false;

    void onSearch({
      orgId,
      q: query,
      kinds: [...parsed.kinds],
      ...(parsed.projectId !== null ? { projectId: parsed.projectId } : {}),
      limit: SEARCH_PAGE_SIZE,
    }).then((result) => {
      if (cancelled) return;
      setResults({ query, hits: result.ok ? result.data : [] });
    });

    return () => {
      cancelled = true;
    };
    // `parsed` is derived from the debounced string; depending on its parts
    // keeps the effect from re-firing on every keystroke.
  }, [open, orgId, onSearch, query, parsed.kinds, parsed.projectId]);

  if (!open) return null;

  return (
    <Dialog
      open={open}
      title="Search"
      description={
        advanced
          ? "Use kind:issue or project:<id> to narrow the search."
          : undefined
      }
      onClose={onClose}
    >
      <Input
        name="q"
        type="search"
        value={raw}
        placeholder={advanced ? "kind:comment deploy failed" : "Search…"}
        onChange={setRaw}
      />

      {advanced && debounced.length > 0 ? (
        <p className="mt-1 text-xs text-neutral-500">{describeQuery(parsed)}</p>
      ) : null}

      <div className="mt-3">
        {pending ? (
          <Spinner size="sm" label="Searching" />
        ) : (
          <SearchResults
            hits={results.query === query ? results.hits : []}
            query={query}
            onSelect={() => onClose()}
          />
        )}
      </div>
    </Dialog>
  );
}
"use client";

/**
 * Ctrl+K overlay shell; the domain layer supplies the groups.
 *
 * Owner A — design system. Knows nothing about commands: it filters the groups
 * it is handed, keeps a single flat active index across group boundaries (so
 * ArrowDown walks from the last item of one group into the first of the next),
 * and reports the chosen id. Registering shortcuts is `useCommandPalette`'s job.
 */
import { useMemo, useState } from "react";
import type { KeyboardEvent, ReactElement } from "react";
import { cn } from "@/lib/cn";
import { isNavKey, matchesQuery, moveActiveIndex } from "./_lib/list-navigation";
import { CONTROL_BORDER, OVERLAY, SURFACE } from "./_lib/tokens";
import { useDismissableLayer, useScrollLock } from "./_lib/use-dismissable-layer";

export type CommandGroup = { heading: string; items: readonly CommandItemSpec[] };

export type CommandItemSpec = { id: string; label: string; hint?: string; shortcut?: string };

export type CommandPaletteProps = { open: boolean; groups: readonly CommandGroup[]; placeholder?: string; onClose: () => void; onSelect: (id: string) => void };

type FlatRow = { item: CommandItemSpec; heading: string; index: number };

/**
 * Filter the groups and number the surviving items in render order. The flat
 * index is what makes arrow navigation continuous across headings.
 */
export function flattenGroups(
  groups: readonly CommandGroup[],
  query: string,
): { rows: FlatRow[]; sections: { heading: string; rows: FlatRow[] }[] } {
  const rows: FlatRow[] = [];
  const sections: { heading: string; rows: FlatRow[] }[] = [];

  for (const group of groups) {
    const kept: FlatRow[] = [];
    for (const item of group.items) {
      const haystack = `${item.label} ${item.hint ?? ""} ${group.heading}`;
      if (!matchesQuery(haystack, query)) continue;
      const row = { item, heading: group.heading, index: rows.length };
      rows.push(row);
      kept.push(row);
    }
    if (kept.length > 0) sections.push({ heading: group.heading, rows: kept });
  }

  return { rows, sections };
}

export function CommandPalette(props: CommandPaletteProps): ReactElement | null {
  const { open, groups, placeholder = "Search commands…", onClose, onSelect } = props;

  const [query, setQuery] = useState("");
  const [activeIndex, setActiveIndex] = useState(0);

  const panelRef = useDismissableLayer<HTMLDivElement>({ open, onDismiss: onClose });
  useScrollLock(open);

  const { rows, sections } = useMemo(
    () => flattenGroups(groups, query),
    [groups, query],
  );

  // A fresh open starts from a clean query. Adjusting state during render on an
  // open/closed transition is the documented alternative to an effect here: the
  // reset lands in the same commit as the open, with no extra paint.
  const [wasOpen, setWasOpen] = useState(open);
  if (open !== wasOpen) {
    setWasOpen(open);
    if (open) {
      setQuery("");
      setActiveIndex(0);
    }
  }

  const choose = (id: string) => {
    onSelect(id);
    onClose();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const key = event.key;
    if (isNavKey(key)) {
      event.preventDefault();
      setActiveIndex((index) => moveActiveIndex(index, key, rows.length));
      return;
    }
    if (key === "Enter") {
      event.preventDefault();
      const row = rows[activeIndex];
      if (row) choose(row.item.id);
    }
  };

  if (!open) return null;

  return (
    <div className={cn(OVERLAY, "flex items-start justify-center p-4 pt-24")}>
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-label="Command palette"
        onKeyDown={handleKeyDown}
        className={cn(SURFACE, "w-full max-w-xl overflow-hidden rounded-lg shadow-2xl")}
      >
        <input
          autoFocus
          type="text"
          role="combobox"
          aria-expanded
          aria-controls="command-palette-list"
          aria-autocomplete="list"
          value={query}
          placeholder={placeholder}
          onChange={(event) => {
            setQuery(event.target.value);
            setActiveIndex(0);
          }}
          className={cn(
            "w-full border-b bg-transparent px-4 py-3 text-sm outline-none placeholder:text-black/40",
            CONTROL_BORDER,
          )}
        />

        <div id="command-palette-list" role="listbox" className="max-h-80 overflow-y-auto py-1">
          {rows.length === 0 ? (
            <p className="px-4 py-6 text-center text-xs text-black/45">
              No commands match “{query}”
            </p>
          ) : null}

          {sections.map((section) => (
            <div key={section.heading} className="py-1">
              <p className="px-4 pb-1 text-[10px] font-semibold uppercase tracking-wide text-black/40">
                {section.heading}
              </p>
              {section.rows.map((row) => (
                <button
                  key={row.item.id}
                  type="button"
                  role="option"
                  aria-selected={row.index === activeIndex}
                  tabIndex={-1}
                  onMouseEnter={() => setActiveIndex(row.index)}
                  onClick={() => choose(row.item.id)}
                  className={cn(
                    "flex w-full items-center gap-3 px-4 py-2 text-left text-sm",
                    row.index === activeIndex && "bg-surface-muted",
                  )}
                >
                  <span className="flex-1 truncate text-black/85 dark:text-white/85">
                    {row.item.label}
                  </span>
                  {row.item.hint !== undefined ? (
                    <span className="truncate text-[11px] text-black/45">
                      {row.item.hint}
                    </span>
                  ) : null}
                  {row.item.shortcut !== undefined ? (
                    <kbd className="rounded border border-black/15 px-1 text-[10px] text-black/55">
                      {row.item.shortcut}
                    </kbd>
                  ) : null}
                </button>
              ))}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
/**
 * Full-page search results.
 *
 * Owner D. The command palette and this page share one action, so the flag
 * check has to live in both places — the palette narrows what it asks for, and
 * this page explains why comments are missing from the results.
 *
 * Must call (do not reimplement): isEnabled
 */

import Link from "next/link";
import type { Metadata } from "next";
import { EmptyState } from "@/components/ui/empty-state";
import { isEnabled } from "@/lib/feature-flags";
import { searchQuerySchema } from "@/schemas/search";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { search as runSearch } from "@/server/services/search-service";
import { loadTenantContext } from "../_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Search",
};

const RESULT_LIMIT = 30;

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  const search = await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const advanced = isEnabled("advanced_search", buildFlagContext(actor, org));
  const query = typeof search.q === "string" ? search.q : "";

  if (query.length === 0) {
    return (
      <div className="space-y-8">
        <SearchHeader orgSlug={orgSlug} query={query} advanced={advanced} />
        <EmptyState
          title="Search this organization"
          description="Type at least one character to look through issues, and — on the higher plans — comments and projects too."
        />
      </div>
    );
  }

  const parsed = searchQuerySchema.safeParse({
    orgId: org.id,
    q: query,
    kinds: advanced ? ["issue", "comment", "project"] : ["issue"],
    limit: RESULT_LIMIT,
  });

  if (!parsed.success) {
    return (
      <div className="space-y-8">
        <SearchHeader orgSlug={orgSlug} query={query} advanced={advanced} />
        <EmptyState title="That query is not valid" description="Try something shorter." />
      </div>
    );
  }

  const page = await runSearch(actor, parsed.data);

  return (
    <div className="space-y-8">
      <SearchHeader orgSlug={orgSlug} query={query} advanced={advanced} />

      {page.items.length === 0 ? (
        <EmptyState title={`Nothing matches “${query}”`} />
      ) : (
        <ul className="space-y-4">
          {page.items.map((hit) => (
            <li key={`${hit.kind}:${hit.id}`}>
              <Link href={hit.href} className="block">
                <span className="text-xs uppercase tracking-wide text-slate-400">
                  {hit.kind}
                </span>
                <span className="mt-0.5 block text-sm font-medium">
                  {hit.title}
                </span>
                <span className="mt-0.5 block text-sm text-slate-600">
                  {hit.snippet}
                </span>
              </Link>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

