/**
 * The search query language (ADR 0007).
 *
 * This is the one parser: the dialog's hint line and the server's query
 * execution both call `parseSearchQuery`, so what the dialog says it understood
 * is what the server searches. It is pure and has no server-only imports.
 */
import type { ProjectId } from "@/types/common";

export type SearchSubjectKind = "issue" | "comment" | "project";

export const SEARCH_KINDS: readonly SearchSubjectKind[] = [
  "issue",
  "comment",
  "project",
];

export interface ParsedSearchQuery {
  /** The free-text remainder, with every field token removed. */
  readonly text: string;
  /** The `kind:` tokens, or the default kind when the query named none. */
  readonly kinds: readonly SearchSubjectKind[];
  /** True when at least one valid `kind:` / `in:` token was typed. */
  readonly hasKindTokens: boolean;
  readonly projectId: ProjectId | null;
  /** Tokens that looked like syntax but named nothing we know. */
  readonly unknownTokens: readonly string[];
}

export const DEFAULT_SEARCH_KINDS: readonly SearchSubjectKind[] = ["issue"];

/**
 * @param raw      what the user typed
 * @param advanced whether the `advanced_search` flag is on for this org; when
 *                 false the whole string is free text and a colon is just a
 *                 character.
 */
export function parseSearchQuery(
  raw: string,
  advanced: boolean,
): ParsedSearchQuery {
  if (!advanced) {
    return {
      text: raw.trim(),
      kinds: DEFAULT_SEARCH_KINDS,
      hasKindTokens: false,
      projectId: null,
      unknownTokens: [],
    };
  }

  const kinds: SearchSubjectKind[] = [];
  const unknown: string[] = [];
  let projectId: ProjectId | null = null;
  let text = "";

  // Words alternate with the whitespace that separated them, so the free text
  // keeps the spacing the user typed between the words that survive.
  const parts = raw.trim().split(/(\s+)/);
  for (let index = 0; index < parts.length; index += 2) {
    const token = parts[index] ?? "";
    if (token.length === 0) continue;

    const separator = token.indexOf(":");
    if (separator <= 0) {
      if (text.length > 0) text += parts[index - 1] ?? " ";
      text += token;
      continue;
    }

    const field = token.slice(0, separator).toLowerCase();
    const value = token.slice(separator + 1);
    if (value.length === 0) {
      unknown.push(token);
      continue;
    }

    if (field === "kind" || field === "in") {
      const kind = value.toLowerCase().replace(/s$/, "") as SearchSubjectKind;
      if (!SEARCH_KINDS.includes(kind)) unknown.push(token);
      else if (!kinds.includes(kind)) kinds.push(kind);
    } else if (field === "project") {
      projectId = value as ProjectId;
    } else {
      unknown.push(token);
    }
  }

  return {
    text,
    kinds: kinds.length > 0 ? kinds : DEFAULT_SEARCH_KINDS,
    hasKindTokens: kinds.length > 0,
    projectId,
    unknownTokens: unknown,
  };
}

/** A one-line explanation of what the parser understood, for the dialog. */
export function describeQuery(parsed: ParsedSearchQuery): string {
  const parts = [`searching ${parsed.kinds.join(", ")}`];
  if (parsed.projectId !== null) parts.push(`in project ${parsed.projectId}`);
  if (parsed.unknownTokens.length > 0) {
    parts.push(`ignoring ${parsed.unknownTokens.join(", ")}`);
  }
  return parts.join(" · ");
}
