import { defineConfig, mergeConfig } from "vitest/config";
import base from "$R/vitest.config";
export default mergeConfig(base, defineConfig({ root: "$R", test: { include: ["/tmp/sv/*.test.ts"], setupFiles: ["$R/tests/setup.ts"] }, server: { fs: { strict: false } } }));
EOF
cat > /tmp/sv/scn.test.ts <<EOF
import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("$R/tests/server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("$R/tests/server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("$R/tests/server/_support/doubles/misc")).rateLimitModule);
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as searchRepo from "@/server/repositories/search-repository";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { emit } from "@/lib/event-bus";
import { createTenant, issueInput, useTemporaryDatabase } from "$R/tests/server/_support/fixtures";
let cleanup: () => void; let detach: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); detach = searchService.registerSearchListeners(); });
afterAll(() => { detach(); cleanup(); });
const all = ["issue", "comment", "project"] as const;
it("scenarios", async () => {
  const ent = await createTenant("ent", "enterprise");
  const st = await createTenant("st", "starter");
  const s = (t: any, q: string, extra: any = {}) => searchService.search(t.actors.member, { orgId: t.org.id, q, kinds: [...all], limit: 25, cursor: null, ...extra });
  const si = await issueService.createIssue(st.actors.member, issueInput(st.org.id, st.project.id, { title: "Release 2: hotfix" }));
  await commentService.createComment(st.actors.member, { orgId: st.org.id, issueId: si.id, body: "Release 2: hotfix too", parentId: null, mentionedUserIds: [] });
  let r = await s(st, "Release 2: hotfix"); expect(r.total).toBe(1); expect(r.items[0].kind).toBe("issue");
  expect((await s(st, "kind:comment hotfix")).total).toBe(0);
  const i1 = await issueService.createIssue(ent.actors.member, issueInput(ent.org.id, ent.project.id, { title: "snake_case 100% done" }));
  await issueService.createIssue(ent.actors.member, issueInput(ent.org.id, ent.project.id, { title: "snake case other back\\\\slash" }));
  const c = await commentService.createComment(ent.actors.member, { orgId: ent.org.id, issueId: i1.id, body: "this is flaky", parentId: null, mentionedUserIds: [] });
  expect((await s(ent, "100%")).total).toBe(1);
  expect((await s(ent, "SNAKE_case")).total).toBe(1);
  expect((await s(ent, "back\\\\slash")).total).toBe(1);
  r = await s(ent, "kind:comment flaky", { kinds: ["issue"] }); expect(r.items.map((x) => x.id)).toEqual([c.id]);
  expect((await s(ent, "in:comments flaky")).total).toBe(1);
  expect((await s(ent, "project:" + ent.project.id + " flaky")).total).toBe(1);
  expect((await s(ent, "project:nope flaky", { projectId: ent.project.id })).total).toBe(0);
  expect((await s(ent, "label:x flaky")).total).toBe(1);
  await searchRepo.deleteSearchDocument(ent.org.id, "comment", c.id);
  await searchRepo.deleteSearchDocument(ent.org.id, "project", ent.project.id);
  const env = { orgId: ent.org.id, actorId: null, occurredAt: new Date().toISOString() as any };
  await emit("search.reindex_requested", { ...env, subjectKind: "comment", subjectId: c.id });
  await emit("search.reindex_requested", { ...env, subjectKind: "project", subjectId: ent.project.id });
  expect((await s(ent, "flaky", { projectId: ent.project.id })).total).toBe(1);
  expect((await s(ent, "kind:project " + ent.project.name)).total).toBe(1);
  await issueService.archiveIssue(ent.actors.member, ent.org.id, i1.id);
  await emit("search.reindex_requested", { ...env, subjectKind: "issue", subjectId: i1.id });
  expect((await s(ent, "100%")).total).toBe(0);
  await searchRepo.upsertSearchDocument(ent.org.id, "comment", c.id, "this is flaky", null);
  const i3 = await issueService.createIssue(ent.actors.member, issueInput(ent.org.id, ent.project.id, { title: "third" }));
  const c3 = await commentService.createComment(ent.actors.member, { orgId: ent.org.id, issueId: i3.id, body: "wobbly", parentId: null, mentionedUserIds: [] });
  await searchRepo.upsertSearchDocument(ent.org.id, "comment", c3.id, "wobbly", null);
  await runSearchReindexJob(ent.org.id);
  expect((await s(ent, "wobbly", { projectId: ent.project.id })).total).toBe(1);
  await commentService.updateComment(ent.actors.member, { orgId: ent.org.id, commentId: c3.id, body: "sturdy" } as any);
  expect((await s(ent, "sturdy", { projectId: ent.project.id })).total).toBe(1);
  expect((await s(ent, "wobbly")).total).toBe(0);
});
EOF
npx vitest run --config /tmp/sv/vitest.config.ts 2>&1 | grep -v "npm warn" | tail -30

